  local x=math.asin(math.max(-1,math.min(1,2*(q.w*q.x-q.y*q.z))))
  return {math.deg(x),math.deg(math.atan(2*(q.w*q.y+q.x*q.z),1-2*(q.x*q.x+q.y*q.y))),math.deg(math.atan(2*(q.w*q.z+q.x*q.y),1-2*(q.x*q.x+q.z*q.z)))}
 elseif p=='m_Alpha' then return {n.spec.alpha or 1}
 elseif p=='m_IsActive' then return {n.spec.active==false and 0 or 1}
 elseif p=='m_FillAmount' then return {n.spec.fill or 1}
 elseif p:sub(1,8)=='m_Color.' then return {(n.spec.color or {r=1,g=1,b=1,a=1})[p:sub(9)]}
 elseif p:sub(1,19)=='m_AnchoredPosition.' then return {(r.m_AnchoredPosition or {x=0,y=0})[p:sub(20)]}
 elseif p:sub(1,16)=='m_LocalPosition.' then return {(r.m_LocalPosition or {x=0,y=0,z=0})[p:sub(17)]}
 elseif p:sub(1,12)=='m_SizeDelta.' then return {(r.m_SizeDelta or {x=0,y=0})[p:sub(13)]} end
